-- Quran glyph bundle — per-ayah PUA chunks keyed to a per-page font file.
CREATE TABLE IF NOT EXISTS glyph_chunks (
    surah  INTEGER NOT NULL,
    ayah   INTEGER NOT NULL,
    chunk  INTEGER NOT NULL,
    p      INTEGER NOT NULL,
    family TEXT    NOT NULL,
    file   TEXT    NOT NULL,
    text   TEXT    NOT NULL,
    PRIMARY KEY (surah, ayah, chunk)
);

